{
  "name": "Water",
  "tables": {
    "glasses": { "fields": {} }
  },
  "queries": {
    "today": { "count": "glasses", "window": "today" },
    "week": { "daily": "glasses", "days": 7 },
    "streak": { "streak": "glasses", "goal": 8 }
  },
  "actions": {
    "drink": { "insert": "glasses" },
    "undo": { "delete": "glasses" }
  },
  "samples": {
    "start of day": { "glasses": [] },
    "halfway": { "glasses": [{ "daysAgo": 0, "repeat": 4 }, { "daysAgo": 1, "repeat": 8 }, { "daysAgo": 2, "repeat": 5 }] },
    "goal met": { "glasses": [{ "daysAgo": 0, "repeat": 8 }, { "daysAgo": 1, "repeat": 9 }, { "daysAgo": 2, "repeat": 8 }, { "daysAgo": 3, "repeat": 3 }] }
  },
  "look": "const GOAL = 8;

function glassIcon(filled) {
  return {
    type: 'symbol',
    name: filled ? 'drop.fill' : 'drop',
    size: 14,
    color: filled ? '#4FC3F7' : '#FFFFFF55'
  };
}

function render(ctx) {
  const count = ctx.data.today;
  const done = count >= GOAL;
  const remaining = Math.max(GOAL - count, 0);
  const medium = ctx.family === 'medium';
  const week = ctx.data.week;
  const last = ctx.data.streak;

  const dots = [];
  for (let i = 0; i < GOAL; i++) {
    dots.push(glassIcon(i < count));
  }

  const summary = {
    type: 'vstack',
    align: 'leading',
    spacing: 4,
    frame: { maxHeight: 'infinity', alignment: 'topLeading' },
    children: [
      { type: 'text', value: 'Water today', size: 13, weight: 'semibold', color: '#9FB3C8' },
      { type: 'text', value: count + ' / ' + GOAL, size: 30, weight: 'bold', design: 'rounded', color: '#FFFFFF', accent: true, lineLimit: 1, minScale: 0.5 },
      { type: 'text', value: done ? 'Goal reached!' : remaining + ' more to go', size: 12, color: '#9FB3C8', lineLimit: 1, minScale: 0.7 },
      { type: 'spacer', minLength: 0 },
      { type: 'hstack', spacing: 8, children: [
        { type: 'button', action: 'undo', children: [
          { type: 'symbol', name: 'arrow.uturn.backward', size: 13, weight: 'bold', color: '#9FB3C8', frame: { width: 34, height: 34 }, background: '#FFFFFF14', clip: 'circle' }
        ] },
        { type: 'button', action: 'drink', children: [
          { type: 'text', value: '+ Glass', size: 14, weight: 'bold', design: 'rounded', color: '#0C1821', frame: { width: 80, height: 34 }, background: '#4FC3F7', clip: 'capsule' }
        ] }
      ] }
    ]
  };

  const grid = {
    type: 'vstack',
    align: 'leading',
    spacing: 6,
    frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
    children: [
      { type: 'hstack', spacing: 4, children: dots.slice(0, 4) },
      { type: 'hstack', spacing: 4, children: dots.slice(4, 8) },
      { type: 'spacer', minLength: 0 },
      { type: 'hstack', spacing: 4, children: week.slice(-7).map(day => ({
        type: 'vstack', spacing: 2, children: [
          { type: 'circle', frame: { width: 10, height: 10 }, fill: day.count >= GOAL ? '#4FC3F7' : null, stroke: day.count >= GOAL ? null : { color: '#FFFFFF66', width: 1 } },
          { type: 'text', value: day.weekday.slice(0, 1), size: 9, color: '#9FB3C8' }
        ] }))
      }
    ]
  };

  return {
    type: 'hstack',
    spacing: 14,
    padding: 14,
    frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
    widgetBackground: { gradient: 'linear', stops: ['#1B3A52', '#0C1821'], from: 'top', to: 'bottom' },
    children: [
      summary,
      medium && grid
    ]
  };
}"
}

